          <div class="toolbar-links">${[['students','users','Учащиеся'],['settings','settings','Настройки']].map(([v,i,label])=>`<button class="btn ${view===v?'active':''}" data-action="nav" data-view="${v}" aria-label="${label}" title="${label}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</div>
