function head(title,description,actions=true){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="head-actions"><button class="btn" data-action="undo" title="Отменить последнее действие" aria-label="Отменить последнее действие" ${!undoStack.length?'disabled':''}>${icon('undo')}</button><button class="btn" data-action="export" aria-label="Выгрузить табель">${icon('download')}<span>Выгрузить</span></button></div>`:''}</div>`;}
function stat(label,value,unit,hint,ic){return `<div class="stat glass"><div class="stat-label">${label}${icon(ic)}</div><div class="stat-value">${value}${unit?`<small>${unit}</small>`:''}</div><div class="stat-hint">${hint}</div></div>`;}
function statsHTML(){const g=group(),t=groupTotals(g,month),ss=monthStudents(g,month),marked=ss.filter(s=>sum(monthTotals(g,s.id,month))>0).length;return `<div class="stats">${stat('В группе',students().length,'чел.','Активный список','users')}${stat('По табелю',fmt(sum(t,state.includePR)),'ч',state.includePR?'Все причины, включая ПР':'Сумма без ПР','clock')}${stat('Причина неизвестна',fmt(t.ПН),'ч','Требуют уточнения · ПН','info')}${stat('С отметками',marked,'чел.',`${monthLabel(month)}`,'calendar')}</div>`;}
function welcome(){return `<section class="welcome glass"><div><div class="eyebrow">Первый шаг · список группы</div><h2>Один раз добавьте людей.<br>Дальше — только отметки.</h2><p>Вставьте список из документа, выберите пару и укажите причину отсутствия. Дневные часы и итоги месяца соберутся автоматически.</p><div class="welcome-actions"><button class="btn primary" data-action="roster">${icon('plus')}Добавить список</button></div></div><div class="mini-sheet" aria-label="Пример подсчёта"><div class="mini-title">Пример · один день</div><div class="mini-row"><span>1-я пара</span><span class="code-badge reason-blue">Б/2</span></div><div class="mini-row"><span>2-я пара</span><span class="code-badge reason-blue">Б/2</span></div><div class="mini-row"><span>Итого за день</span><span>Б/4</span></div></div></section>`;}
function renderDay(){const g=group(),ls=lessons(),l=currentLesson(),start=monday(selectedDate);return head('Посещаемость',`Группа ${esc(g.name)} <span aria-hidden="true">·</span> ${monthLabel(month)}`)+(students().length?'':welcome())+`<section class="day-calendar glass" aria-label="Дата и дни недели"><div class="section-row date-header"><div><h2 style="text-transform:capitalize">${ruDate(selectedDate,{weekday:'long',day:'numeric',month:'long'})}</h2><p>${ls.length?`${ls.length} занятий · ${fmt(ls.reduce((n,l)=>n+l.hours,0))} академических часов`:'Нет занятий в загруженном расписании'}</p></div><div class="date-controls"><button class="icon-btn" data-action="date-prev" aria-label="Предыдущая неделя">${icon('left')}</button><input id="dateInput" type="date" value="${selectedDate}" aria-label="Выбрать дату"><button class="icon-btn" data-action="date-next" aria-label="Следующая неделя">${icon('chevron')}</button><button class="btn small" data-action="today">Сегодня</button></div></div><div class="week-strip">${Array.from({length:7},(_,i)=>{const d=addDays(start,i),n=lessonsFor(schedule,g,d).length;return `<button class="week-day ${d===selectedDate?'selected':''} ${d===today()?'today':''}" data-action="select-date" data-date="${d}" aria-label="${ruDate(d,{weekday:'long',day:'numeric',month:'long'})}${d===today()?', сегодня':''}. Занятий: ${n}" ${d===today()?'aria-current="date"':''} aria-pressed="${d===selectedDate}"><span class="dow">${ruDate(d,{weekday:'short'})}${d===today()?'<i class="today-marker" aria-hidden="true"></i>':''}</span><span class="date">${Number(d.slice(-2))}</span><span class="dots" aria-hidden="true">${Array.from({length:Math.min(n,5)},()=>'<i></i>').join('')}</span></button>`}).join('')}</div></section><div class="day-grid"><div><div class="section-row"><span class="eyebrow">${ls.length?'Выберите занятие':'Расписание дня'}</span><button class="btn subtle small" data-action="lesson-new">${icon('plus')}Занятие</button></div>${ls.length?`<div class="lesson-scroll">${ls.map(x=>`<button class="lesson-card ${x.id===selectedLesson?'selected':''}" data-action="lesson" data-id="${esc(x.id)}" aria-pressed="${x.id===selectedLesson}"><div class="lesson-top"><span class="lesson-num">${esc(x.num)} пара</span><span>${esc(x.time)}</span></div><h3>${esc(x.subject)}</h3><div class="lesson-foot"><span>${esc(TYPES[x.type]||'Занятие')} · ${fmt(x.hours)} ч</span>${g.reviewed[selectedDate]?.[x.id]?icon('check'):''}</div></button>`).join('')}</div>`:`<div class="no-lessons"><h3>Свободный день — или расписание изменилось</h3><p class="note" style="margin-top:8px">Добавьте занятие вручную. Если переносите готовые суммы из журнала, откройте дневной ввод в табеле.</p><button class="btn small" data-action="nav" data-view="month" style="margin-top:14px">Открыть табель</button></div>`}${l&&l.hours===0?`<div class="note-box" style="margin-bottom:12px">Для информационного и кураторского часа по умолчанию 0 учётных часов. Укажите нужную продолжительность через «Изменить занятие», если эти часы входят в ваш табель.</div>`:''}<section class="table-card glass"><div class="table-toolbar"><div><h3>Список группы <span class="muted">${students().length}</span></h3><small>${l?`Отметки на ${esc(l.num)}-й паре · ${fmt(l.hours)} ч`:'Добавьте занятие для отметок по парам'}</small></div><div class="search">${icon('search')}<input id="studentSearch" type="search" placeholder="Найти учащегося" aria-label="Найти учащегося" value="${esc(query)}"></div></div><div id="rosterContent">${rosterHTML()}</div><div class="table-bottom"><span>${l&&g.reviewed[selectedDate]?.[l.id]?`${icon('check')} Занятие сверено`:'Пустая клетка = присутствие'}</span><div style="display:flex;gap:5px"><button class="btn small subtle" data-action="roster" title="Добавить учащихся">${icon('users')}</button>${l?`<button class="btn small subtle" data-action="lesson-edit" aria-label="Изменить занятие" title="Изменить занятие">${icon('edit')}</button>`:''}</div></div></section><div class="section-row" style="margin-top:13px"><p class="note">1 пара = 2 часа. Отмечайте только пропуски и ПР.</p><button class="btn subtle small" data-action="bulk" ${!l||!students().length?'disabled':''}>Нескольким сразу ${icon('arrow')}</button></div></div><aside class="day-aside">${summaryHTML()}<section class="aside-card glass"><h3>Обозначения журнала</h3><p class="caption">По вашей памятке факультета права</p><div class="legend">${REASONS.map(r=>`<div class="legend-item"><span class="code-badge reason-${r.color}">${r.code}</span><span>${r.code==='ПР'?'Присутствие без участия · физкультура':esc(r.name)}</span></div>`).join('')}</div></section></aside></div>`;}
function rosterHTML(){const g=group(),ls=currentLesson(),ss=students().filter(s=>s.name.toLowerCase().includes(query.toLowerCase()));if(!students().length)return `<div class="empty-roster">${icon('users')}<h3>Здесь будет ваша группа</h3><p>Добавьте фамилии списком.<br>Отметки с фотографии не переносятся автоматически.</p><button class="btn small" data-action="roster">${icon('plus')}Добавить учащихся</button></div>`;if(!ss.length)return `<div class="no-results">Никого не нашли. Попробуйте другую часть фамилии.</div>`;return `<table class="roster-table"><thead><tr><th>№</th><th>Учащийся</th><th class="status-col">На паре</th><th class="total-col">За день</th></tr></thead><tbody>${ss.map(s=>{const code=ls?statusFor(g,selectedDate,ls.id,s.id):'',r=reason(code),t=dayTotals(g,s.id,selectedDate);return `<tr><td class="num">${students().indexOf(s)+1}</td><td><button class="student-link" data-action="profile" data-id="${esc(s.id)}"><span class="avatar">${esc(initials(s.name))}</span>${esc(s.name)}</button></td><td class="status-col"><button class="status-btn ${code==='+'?'present':r?`reason-${r.color}`:''}" data-action="status" data-id="${esc(s.id)}" aria-label="${esc(s.name)}: ${code==='+'?'присутствует':code==='daily'?'дневной итог':r?esc(r.name):'присутствует'}" ${!ls?'disabled':''}>${code==='+'?`${icon('check')}Есть`:code==='daily'?'Дневной итог':code||'Есть'}</button></td><td class="total-col"><button class="btn subtle small" data-action="daily" data-id="${esc(s.id)}" title="Итог за день">${sum(t,state.includePR)?`${fmt(sum(t,state.includePR))} ч`:'—'}</button></td></tr>`}).join('')}</tbody></table>`;}
function summaryHTML(){const t=groupTotals(group(),month),total=sum(t,state.includePR),max=Math.max(1,...CODES.map(c=>t[c]));return `<section class="aside-card glass"><div class="section-row" style="margin-bottom:0"><h3>За месяц</h3><span class="pill">${ruDate(month+'-01',{month:'short'}).replace('.','')}</span></div><p class="caption">Сумма по всей группе</p><div class="reason-bars">${REASONS.filter(r=>['Б','УП','ПН','ПР'].includes(r.code)||t[r.code]).map(r=>`<div><div class="reason-bar-head"><span>${r.code} · ${r.code==='ПР'?'Без участия':r.code==='УП'?'По заявлению':r.code==='ПН'?'Неизвестна':r.name}</span><strong>${fmt(t[r.code])} ч</strong></div><div class="bar-track"><div class="bar-fill" style="width:${Math.round(t[r.code]/max*100)}%;background:var(--${r.color})"></div></div></div>`).join('')}</div><div style="display:flex;justify-content:space-between;border-top:1px solid var(--line);padding-top:15px;margin-top:20px;font-size:12px"><span class="muted">Всего по табелю</span><strong>${fmt(total)} ч</strong></div><p class="note" style="margin-top:14px">${state.includePR?'ПР входит в итог, как в вашем образце.':'ПР показывается отдельно и не входит в итог.'}</p></section>`;}
function renderMonth(){const g=group(),ds=monthDays(month),ss=monthStudents(g,month),total=groupTotals(g,month);return head('Месячный табель','Вносите обозначения вручную. Часы и итоги считаются автоматически.')+`<div class="section-row"><div class="month-controls"><button class="icon-btn" data-action="month-prev" aria-label="Предыдущий месяц">${icon('left')}</button><input type="month" id="monthInput" value="${month}" aria-label="Месяц табеля"><button class="icon-btn" data-action="month-next" aria-label="Следующий месяц">${icon('chevron')}</button></div><button class="btn small" data-action="print">${icon('print')}Печать / PDF</button></div><section class="table-card glass"><div class="table-toolbar"><div><h3>Группа ${esc(g.name)}</h3><small>Пустая клетка — присутствие. Нажмите на день: Б/8 или ПН/2; ПР/2; Б/2.</small></div><span class="pill">Черновик</span></div>${ss.length?`<div class="table-scroll" data-month="${month}"><table class="monthly-table"><thead><tr><th class="sticky-name">Учащийся</th>${ds.map(d=>`<th class="${dateObj(d).getUTCDay()===0?'weekend':''} ${d===today()?'today-head':''}">${Number(d.slice(-2))}<br><span style="font-size:8px">${ruDate(d,{weekday:'short'})}</span></th>`).join('')}${CODES.map(c=>`<th>${c}</th>`).join('')}<th class="sticky-total">Всего</th></tr></thead><tbody>${ss.map(s=>{const mt=monthTotals(g,s.id,month);return `<tr><td class="sticky-name"><button class="student-link" data-action="profile" data-id="${esc(s.id)}">${esc(s.name)}${s.archived?' *':''}</button></td>${ds.map(d=>{const dt=dayTotals(g,s.id,d),has=CODES.some(c=>dt[c]);return `<td class="${dateObj(d).getUTCDay()===0?'weekend':''}"><button class="day-cell" data-action="daily" data-id="${esc(s.id)}" data-date="${d}" aria-label="${esc(s.name)}, ${ruDate(d)}: ${compact(dt)||'присутствие'}">${has?CODES.filter(c=>dt[c]).map(c=>`<span class="cell-mark reason-${reason(c).color}">${c}/${fmt(dt[c])}</span>`).join(''):'<span aria-hidden="true">&nbsp;</span>'}</button></td>`}).join('')}${CODES.map(c=>`<td style="color:var(--${reason(c).color})">${mt[c]?fmt(mt[c]):'—'}</td>`).join('')}<td class="sticky-total">${fmt(sum(mt,state.includePR))}</td></tr>`}).join('')}<tr class="tfoot"><td class="sticky-name">Всего по группе</td>${ds.map(d=>`<td>${fmt(ss.reduce((n,s)=>n+sum(dayTotals(g,s.id,d),state.includePR),0))||'—'}</td>`).join('')}${CODES.map(c=>`<td>${fmt(total[c])}</td>`).join('')}<td class="sticky-total">${fmt(sum(total,state.includePR))}</td></tr></tbody></table></div>`:`<div class="empty-roster">${icon('table')}<h3>Табель готов к заполнению</h3><p>Начните со списка вашей учебной группы.</p><button class="btn primary" data-action="roster">Добавить учащихся</button></div>`}<div class="table-bottom"><span>Таблицу можно прокручивать вправо. Фамилии и итог закреплены.</span><span>${ds.length} дней · ${ss.length} учащихся</span></div></section><div class="note-box" style="margin-top:17px">В одной ячейке может быть несколько причин: например, Б/4 и ПН/2. ${state.includePR?'«Всего» включает ПР, как на фотографии журнала.':'«Всего» не включает ПР — это выбрано в настройках.'} Пустая ячейка означает присутствие.</div>`;}
function renderStudents(){const g=group(),ss=students().filter(s=>s.name.toLowerCase().includes(query.toLowerCase()));return head('Учащиеся','Личная история отметок и часы по каждой причине.')+`<div class="section-row"><div class="month-controls"><button class="icon-btn" data-action="month-prev" aria-label="Предыдущий месяц">${icon('left')}</button><input type="month" id="monthInput" value="${month}" aria-label="Месяц"><button class="icon-btn" data-action="month-next" aria-label="Следующий месяц">${icon('chevron')}</button></div><button class="btn small" data-action="roster">${icon('plus')}Список группы</button></div><div class="search" style="max-width:300px;margin-bottom:18px">${icon('search')}<input type="search" id="studentSearch" value="${esc(query)}" placeholder="Найти учащегося" aria-label="Найти учащегося"></div><div id="studentCards" class="students-grid">${studentCards(ss)}</div>${!students().length?welcome():''}${g.students.some(s=>s.archived)?`<div class="archive-list"><div class="eyebrow">В архиве · история сохранена</div>${g.students.filter(s=>s.archived).map(s=>`<div class="archive-item"><button class="student-link" data-action="profile" data-id="${esc(s.id)}">${esc(s.name)}</button><button class="btn small subtle" data-action="restore-student" data-id="${esc(s.id)}">Восстановить</button></div>`).join('')}</div>`:''}`;}
function studentCards(ss){return ss.map(s=>{const t=monthTotals(group(),s.id,month),n=monthDays(month).filter(d=>sum(dayTotals(group(),s.id,d))>0).length;return `<section class="student-card glass"><div class="student-card-top"><span class="avatar">${esc(initials(s.name))}</span><div><h3>${esc(s.name)}</h3><small>${esc(s.rank||'Учебная группа '+group().name)}</small></div></div><div class="student-card-foot"><div><strong>${fmt(sum(t,state.includePR))}</strong> <span class="muted">ч · ${n} дн.</span></div><button class="btn small subtle" data-action="profile" data-id="${esc(s.id)}">Подробнее ${icon('arrow')}</button></div>${t.ПН?`<span class="pill reason-rose" style="align-self:flex-start">ПН · ${fmt(t.ПН)} ч — уточнить причину</span>`:''}</section>`}).join('')||'<div class="no-results">Список пока пуст</div>';}
function renderSettings(){return head('Настройки','Группа, расписание и сохранность данных.',false)+`<div class="settings-grid"><section class="settings-card glass"><h2>Ваша учебная группа</h2><p>Группа 4502. Список из 30 учащихся добавлен в указанном вами порядке. Фамилии можно редактировать в карточках учащихся.</p><div class="note-box" style="margin-top:17px">Группа <strong>4502</strong> · расписание 4502<br>Пустая клетка = присутствие<br>1 пара = 2 академических часа</div><button class="btn small" data-action="roster">${icon('users')}Дополнить список учащихся</button></section><section class="settings-card glass"><h2>Сохранение и перенос</h2><p>Изменения автоматически сохраняются в этом браузере. Для другого устройства скачайте резервную копию и восстановите её там. Очистка данных браузера удаляет местный журнал.</p><button class="btn" data-action="backup">${icon('download')}Резервная копия</button><br><button class="btn" data-action="restore">${icon('upload')}Восстановить из файла</button>${rawBroken?`<br><button class="btn danger" data-action="broken-download">Скачать исходные данные</button><br><button class="btn danger" data-action="reset-broken">Начать новый журнал</button>`:''}<p style="margin-top:14px">Файл копии содержит список группы 4502, все месяцы, отметки и расписание.</p></section><section class="settings-card glass"><h2>Источник расписания</h2><p>Данные вашего <a href="https://qppaza.github.io/myschedule/" target="_blank" rel="noopener">расписания</a>. ${schedule.weekDates.length?`Период: ${ruDate(schedule.weekDates[0],{day:'numeric',month:'short',year:'numeric'})} — ${ruDate(addDays(schedule.weekDates.at(-1),5),{day:'numeric',month:'short',year:'numeric'})}.`:''}<br>Копия обновлена: ${esc(scheduleUpdated||'неизвестно')}. Обновление выполняется по кнопке.</p><button class="btn" data-action="refresh-schedule" ${refreshing?'disabled':''}>${icon('refresh')}${refreshing?'Обновляем…':'Обновить с сайта'}</button><br><button class="btn small" data-action="import-schedule">${icon('upload')}Импорт расписания</button><p style="margin-top:14px">Подойдут JSON с данными или сохранённый HTML вашего расписания. Уже внесённые часы сохраняются при обновлении источника.</p></section><section class="settings-card glass"><h2>Подсчёт и внешний вид</h2><div class="note-box" style="margin-top:17px">Б, УП, ПН, СБ, ОМ, Ц и ПР — все семь обозначений входят в «Всего». Пустая клетка даёт 0 часов пропусков.</div><p style="margin-top:15px">Все отметки вносите вы. Расписание только подсказывает занятия и часы; автоматически пропуски не появляются.</p><div class="theme-options">${[['light','sun','Светлая'],['dark','moon','Тёмная'],['system','system','Авто']].map(([t,i,n])=>`<button class="btn small ${state.theme===t?'selected':''}" data-action="set-theme" data-theme="${t}">${icon(i)}${n}</button>`).join('')}</div></section></div>`;}
function studentProfile(id){const s=group().students.find(s=>s.id===id);if(!s)return;const t=monthTotals(group(),id,month),entries=monthDays(month).filter(d=>sum(dayTotals(group(),id,d))>0);modal(esc(s.name),`${esc(group().name)} · ${monthLabel(month)}${s.archived?' · в архиве':''}`,`<div class="profile-stats"><div class="profile-stat"><small class="muted">Всего по табелю</small><strong>${fmt(sum(t,state.includePR))} ч</strong></div><div class="profile-stat"><small class="muted">Дней с пропусками</small><strong>${entries.length}</strong></div></div><div class="profile-bars">${REASONS.map(r=>`<span class="code-badge reason-${r.color}">${r.code} · ${fmt(t[r.code])} ч</span>`).join('')}</div><h3 style="margin-bottom:8px">История за месяц</h3><div class="profile-history">${entries.map(d=>{const daily=group().daily[d]?.[id],records=Object.values(group().marks[d]||{}).map(rs=>rs[id]).filter(r=>r&&r.code!=='+');return `<div class="history-row"><div><strong>${ruDate(d,{day:'numeric',month:'long',weekday:'short'})} · ${compact(dayTotals(group(),id,d))}</strong><small>${daily?`Дневной итог из журнала${daily.note?` · ${esc(daily.note)}`:''}`:records.map(r=>`${esc(r.subject)} · ${r.code}/${fmt(r.hours)}`).join('<br>')}</small></div><button data-action="daily" data-id="${esc(id)}" data-date="${d}">Изменить</button></div>`}).join('')||'<p class="note" style="padding:15px 0">В этом месяце пропуски не внесены.</p>'}</div><div class="modal-foot"><button class="btn" data-action="edit-student" data-id="${esc(id)}">${icon('edit')}Данные учащегося</button><button class="btn primary" data-action="close">Готово</button></div>`);}
function rosterDialog(){modal('Список группы',`Группа ${esc(group().name)} · ${students().length} учащихся`,`<p class="note" style="margin-bottom:16px">Вставьте фамилии и инициалы: каждый человек с новой строки. Номера в начале строк будут убраны. Существующие учащиеся и отметки сохранятся.</p><form id="rosterForm"><div class="field"><label for="rosterNames">Добавить учащихся</label><textarea id="rosterNames" rows="9" placeholder="Иванов И. И.&#10;Петрова А. С.&#10;Сидоров М. А." required></textarea></div><div class="check-label"><input type="checkbox" id="sortRoster" checked><label for="sortRoster">Расположить весь список по алфавиту</label></div><div id="formError" class="form-error"></div><div class="modal-foot"><button type="button" class="btn" data-action="close">Отмена</button><button class="btn primary" type="submit">Добавить в группу</button></div></form>`);$('#rosterForm').onsubmit=e=>{e.preventDefault();let names=$('#rosterNames').value.split(/\r?\n/).map(n=>n.replace(/^\s*\d+[.)\s\t-]+/,'').trim().replace(/\s+/g,' ')).filter(Boolean);if(!names.length){$('#formError').textContent='Вставьте хотя бы одно имя.';return;}if(names.length+group().students.length>500){$('#formError').textContent='Слишком большой список: не более 500 учащихся в группе.';return;}const sort=$('#sortRoster').checked;let count=0;change(()=>{const known=new Set(group().students.map(s=>s.name.toLowerCase().replace(/\s+/g,'')));for(const name of names){const key=name.toLowerCase().replace(/\s+/g,'');if(known.has(key))continue;group().students.push({id:uid(),name,rank:'',archived:false});known.add(key);count++;}if(sort)group().students.sort((a,b)=>a.name.localeCompare(b.name,'ru'));},`Добавлено: ${count}`);closeModal();toast(count?`Добавлено учащихся: ${count}`:'Все имена уже есть в списке');};}
function editStudent(id){const s=group().students.find(x=>x.id===id);if(!s)return;modal('Данные учащегося','Изменение имени сохраняет всю историю отметок.',`<form id="studentForm"><div class="field"><label for="editName">Фамилия, инициалы</label><input id="editName" value="${esc(s.name)}" maxlength="150" required></div><div class="field"><label for="editRank">Специальное звание · необязательно</label><input id="editRank" value="${esc(s.rank||'')}" maxlength="80"></div><div class="modal-foot"><button class="btn danger" type="button" data-action="archive-student" data-id="${esc(id)}">${icon('archive')}${s.archived?'В архиве':'В архив'}</button><button class="btn primary" type="submit">Сохранить</button></div></form>`);$('#studentForm').onsubmit=e=>{e.preventDefault();const name=$('#editName').value.trim(),rank=$('#editRank').value.trim();if(!name)return;change(()=>{s.name=name;s.rank=rank;},'Данные обновлены');closeModal();};}
function statusDialog(id){const s=group().students.find(s=>s.id===id),l=currentLesson();if(!s||!l)return;const code=statusFor(group(),selectedDate,l.id,id);if(code==='daily'){dailyDialog(id,selectedDate);return;}modal(esc(s.name),`${ruDate(selectedDate)} · ${esc(l.subject)} · ${fmt(l.hours)} ч`,`<div class="code-options">${[{code:'+',name:'Присутствует',color:'teal'},...REASONS].map(r=>`<button class="code-option ${code===r.code?'selected':''}" data-mark="${r.code}" ${r.code==='ПР'&&!l.pe?'disabled':''}><span class="code-badge reason-${r.color}">${r.code==='+'?icon('check'):r.code}</span><span>${esc(r.name)}</span><span class="option-hours">${r.code==='+'?'0 ч':`${fmt(l.hours)} ч`}</span></button>`).join('')}<button class="code-option" data-mark="">${icon('x')}Очистить · присутствует</button></div>${!l.pe?'<p class="note" style="margin-top:12px">ПР доступно только для физкультуры. При необходимости измените тип занятия.</p>':''}`);$('#modal').querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{const c=b.dataset.mark;change(()=>{writeMark(id,c,l);},c?`Отметка: ${c==='+'?'присутствует':c}`:'Отметка очищена: присутствует');closeModal();});}
function writeMark(id,code,l){const g=group();g.marks[selectedDate]??={};g.marks[selectedDate][l.id]??={};if(code&&code!=='+')g.marks[selectedDate][l.id][id]={code,hours:l.hours,subject:l.subject,num:l.num,time:l.time,pe:!!l.pe};else delete g.marks[selectedDate][l.id][id];}
function dailyDialog(id,date=selectedDate){const s=group().students.find(x=>x.id===id);if(!s)return;const t=dayTotals(group(),id,date),existing=group().daily[date]?.[id],scheduled=lessonsFor(schedule,group(),date).reduce((n,l)=>n+l.hours,0);modal(`Пропуски за ${ruDate(date)}`,esc(s.name),`<form id="dailyForm"><div class="field"><label for="quickEntry">Обозначение и часы</label><input id="quickEntry" value="${esc(compact(t))}" placeholder="ПН/2; ПР/2; Б/2" maxlength="150" autocomplete="off" autofocus><small>Можно несколько причин через точку с запятой. Пустое поле — присутствие.</small></div><p class="note" style="margin-bottom:17px">Введите часы, как в бумажном журнале: Б/8 → 8 в поле «Б». В день можно указать несколько причин. ${scheduled?`По расписанию: ${fmt(scheduled)} ч.`:''}</p><div class="hours-grid">${REASONS.map(r=>`<div class="hours-item"><label for="h-${r.code}" title="${esc(r.name)}"><span class="code-badge reason-${r.color}">${r.code}</span></label><input type="number" min="0" max="24" step="1" id="h-${r.code}" data-hours="${r.code}" value="${t[r.code]||''}" placeholder="0" aria-label="${esc(r.name)}: часов"></div>`).join('')}</div><div class="field" style="margin-top:18px"><label for="dailyNote">Примечание · необязательно</label><input id="dailyNote" maxlength="300" value="${esc(existing?.note||'')}" placeholder="Например, причина уточнена по заявлению"></div><div class="note-box">Сохранение дневного итога заменит отметки по парам для этого человека за этот день. Двойного подсчёта не будет. Действие можно отменить.</div><p class="note" style="margin-top:10px">ПР — только присутствие без участия на физкультуре. При прямом вводе сверяйте часы с журналом.</p><div id="formError" class="form-error"></div><div class="modal-foot"><button type="button" class="btn danger" id="clearDay">Очистить день</button><button class="btn primary" type="submit">Сохранить итог</button></div></form>`);$('#dailyForm').onsubmit=e=>{e.preventDefault();const hours=emptyTotals();$('#modal').querySelectorAll('[data-hours]').forEach(x=>hours[x.dataset.hours]=Number(x.value)||0);if(CODES.some(c=>!Number.isInteger(hours[c])||hours[c]<0)||sum(hours)>24){$('#formError').textContent='Укажите целое число часов от 0 до 24. Общая сумма за день не должна превышать 24.';return;}if($('#quickEntry').dataset.invalid){$('#formError').textContent=$('#quickEntry').dataset.invalid;return;}const note=$('#dailyNote').value.trim();if(scheduled&&sum(hours)>scheduled&&!$('#dailyForm').dataset.confirmed){$('#formError').textContent=`Внесено ${sum(hours)} ч, а в расписании ${scheduled} ч. Если это верно по журналу, нажмите «Сохранить итог» ещё раз.`;$('#dailyForm').dataset.confirmed='yes';return;}change(()=>{group().daily[date]??={};group().daily[date][id]={hours,note};for(const rs of Object.values(group().marks[date]||{}))delete rs[id];},'Дневной итог сохранён');closeModal();};$('#clearDay').onclick=()=>confirmModal('Очистить отметки за день?',`Все отметки ${s.name} за ${ruDate(date)} будут удалены. Действие можно отменить.`,()=>{change(()=>{delete group().daily[date]?.[id];for(const [lid,rs] of Object.entries(group().marks[date]||{})){delete rs[id];delete group().reviewed[date]?.[lid];}},'День очищен');},'Очистить');$('#quickEntry').oninput=()=>{delete $('#dailyForm').dataset.confirmed;try{const h=parseEntry($('#quickEntry').value);$('#modal').querySelectorAll('[data-hours]').forEach(x=>x.value=h[x.dataset.hours]||'');delete $('#quickEntry').dataset.invalid;$('#formError').textContent='';}catch(err){$('#quickEntry').dataset.invalid=err.message;$('#formError').textContent=err.message;}};$('#modal').querySelectorAll('[data-hours]').forEach(x=>x.oninput=()=>{delete $('#dailyForm').dataset.confirmed;const h=emptyTotals();$('#modal').querySelectorAll('[data-hours]').forEach(i=>h[i.dataset.hours]=Number(i.value)||0);$('#quickEntry').value=compact(h);delete $('#quickEntry').dataset.invalid;$('#formError').textContent='';});}
function lessonDialog(edit=false){const l=edit?currentLesson():null;modal(l?'Изменить занятие':'Добавить занятие',ruDate(selectedDate,{weekday:'long',day:'numeric',month:'long'}),`<form id="lessonForm"><div class="field"><label for="lessonSubject">Предмет</label><input id="lessonSubject" value="${esc(l?.subject||'')}" placeholder="Название учебной дисциплины" maxlength="200" required></div><div class="field-row"><div class="field"><label for="lessonNumber">Номер пары</label><input type="number" id="lessonNumber" min="1" max="12" value="${Number(l?.num)||lessons().length+1}" required></div><div class="field"><label for="lessonHours">Академических часов</label><input type="number" id="lessonHours" min="0" max="12" step="1" value="${l?.hours??2}" required></div></div><div class="field"><label for="lessonTime">Время · необязательно</label><input id="lessonTime" maxlength="30" value="${esc(l?.time||'')}" placeholder="08:30–09:50"></div><label class="check-label"><input type="checkbox" id="lessonPe" ${l?.pe?'checked':''}><span>Физкультура — разрешить обозначение ПР</span></label><p class="note" style="margin-top:14px">Изменения применяются только к выбранной дате и группе. ${l?'Часы уже внесённых отметок этой пары будут пересчитаны.':''}</p><div id="formError" class="form-error"></div><div class="modal-foot"><button type="button" class="btn" data-action="close">Отмена</button><button class="btn primary" type="submit">Сохранить</button></div></form>`);$('#lessonForm').onsubmit=e=>{e.preventDefault();const entry={id:l?.id||`c${uid()}`,num:Number($('#lessonNumber').value),subject:$('#lessonSubject').value.trim(),hours:Number($('#lessonHours').value),time:$('#lessonTime').value.trim(),pe:$('#lessonPe').checked,type:l?.type||'other'};if(!entry.subject||!Number.isInteger(entry.hours)||entry.hours<0||entry.hours>12)return;if(l&&!entry.pe&&Object.values(group().marks[selectedDate]?.[l.id]||{}).some(r=>r.code==='ПР')){$('#formError').textContent='На этой паре уже есть ПР. Сначала измените эти отметки, затем снимите признак физкультуры.';return;}change(()=>{if(l){group().lessonEdits[selectedDate]??={};group().lessonEdits[selectedDate][l.id]=entry;for(const r of Object.values(group().marks[selectedDate]?.[l.id]||{}))Object.assign(r,{hours:entry.hours,subject:entry.subject,num:entry.num,time:entry.time,pe:entry.pe});}else{group().customLessons[selectedDate]??=[];group().customLessons[selectedDate].push(entry);}selectedLesson=entry.id;},'Занятие сохранено');closeModal();};}
function bulkDialog(){const l=currentLesson();if(!l)return;modal('Отметить нескольких',`${esc(l.subject)} · ${ruDate(selectedDate)}`,`<form id="bulkForm"><div class="field"><label for="bulkCode">Причина</label><select id="bulkCode"><option value="+">Присутствуют</option>${REASONS.filter(r=>r.code!=='ПР'||l.pe).map(r=>`<option value="${r.code}">${r.code} — ${esc(r.name)}</option>`).join('')}</select></div><div style="max-height:300px;overflow:auto;display:grid;gap:12px">${students().map(s=>`<label class="check-label"><input type="checkbox" name="bulkStudent" value="${esc(s.id)}" ${group().daily[selectedDate]?.[s.id]?'disabled':''}><span>${esc(s.name)}${group().daily[selectedDate]?.[s.id]?' · дневной итог':''}</span></label>`).join('')}</div><div id="formError" class="form-error"></div><div class="modal-foot"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn primary" type="submit">Применить отметку</button></div></form>`);$('#bulkForm').onsubmit=e=>{e.preventDefault();const ids=[...$('#modal').querySelectorAll('[name=bulkStudent]:checked')].map(x=>x.value),code=$('#bulkCode').value;if(!ids.length){$('#formError').textContent='Выберите хотя бы одного учащегося.';return;}change(()=>ids.forEach(id=>writeMark(id,code,l)),`Отметка внесена: ${ids.length} чел.`);closeModal();};}
function groupDialog(){modal('Новая учебная группа','Табель учебной группы 4502.',`<form id="newGroupForm"><div class="field"><label for="newGroupName">Название или номер группы</label><input id="newGroupName" maxlength="80" placeholder="Например, 4504" required></div><div class="field"><label for="newGroupSource">Расписание</label><select id="newGroupSource"><option value="">Добавлять занятия вручную</option>${schedule.groups.map(g=>`<option value="${esc(g)}">Как у группы ${esc(g)}</option>`).join('')}</select></div><div class="modal-foot"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn primary">Создать группу</button></div></form>`);$('#newGroupForm').onsubmit=e=>{e.preventDefault();const name=$('#newGroupName').value.trim(),source=$('#newGroupSource').value;if(!name)return;change(()=>{const id=uid();state.groups[id]=makeGroup(name,source);state.activeGroup=id;query='';selectedLesson=null;},'Группа создана');closeModal();};}
function download(data,filename,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function backup(){download(JSON.stringify({kind:'attendance-backup',version:1,exportedAt:new Date().toISOString(),state,schedule,scheduleUpdated},null,2),`tabel-backup-${today()}${demo?'-demo':''}.json`,'application/json');toast(demo?'Скачана копия демонстрации':'Резервная копия скачана');}
function exportDialog(){modal('Выгрузить табель',`Группа ${esc(group().name)} · ${monthLabel(month)}`,`<div class="export-options"><button class="btn" data-action="print">${icon('print')}<span>Печать / сохранить в PDF<small>А4, альбомная ориентация, все причины и итоги</small></span></button><button class="btn" data-action="html">${icon('file')}<span>Скачать печатный табель<small>Самостоятельный HTML-файл, открывается в браузере</small></span></button><button class="btn" data-action="csv">${icon('table')}<span>Таблица для Excel (.csv)<small>Дневные записи и итоговые столбцы</small></span></button><button class="btn" data-action="backup">${icon('download')}<span>Полная резервная копия (.json)<small>Весь список, месяцы, отметки и расписание</small></span></button></div><p class="note" style="margin-top:18px">В печать попадёт вся группа, независимо от поиска на экране. Табель помечается как черновик для сверки с журналом.</p>`);}
function printTable(){const win=window.open('','_blank');if(!win){toast('Разрешите открытие новой вкладки или скачайте печатный HTML.');return;}win.document.open();win.document.write(printHTML(group(),month,state.includePR));win.document.close();setTimeout(()=>{try{win.focus();win.print();}catch{}},350);}
function exportCsv(){const ds=monthDays(month),rows=[['№','Спец. звание','Фамилия, инициалы',...ds.map(d=>ruDate(d,{day:'2-digit',month:'2-digit'})),...CODES,`Всего${state.includePR?' (с ПР)':' (без ПР)'}`]],ss=monthStudents(group(),month);ss.forEach((s,i)=>{const t=monthTotals(group(),s.id,month);rows.push([i+1,s.rank||'',s.name,...ds.map(d=>compact(dayTotals(group(),s.id,d))),...CODES.map(c=>t[c]),sum(t,state.includePR)]);});const all=groupTotals(group(),month);rows.push(['','','Итого по группе',...ds.map(d=>ss.reduce((n,s)=>n+sum(dayTotals(group(),s.id,d),state.includePR),0)),...CODES.map(c=>all[c]),sum(all,state.includePR)]);const safe=x=>{let s=String(x);if(typeof x==='string'&&/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download('\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),`tabel-${group().name.replace(/[^\p{L}\p{N}-]/gu,'_')}-${month}.csv`,'text/csv;charset=utf-8');toast('Таблица CSV скачана');}
function help(){modal('Как вести табель','Короткий путь от бумажного журнала к месячному итогу.',`<div style="display:grid;gap:18px"><div><h3>1. Проверьте список группы</h3><p class="note">Ваш список из 30 человек уже добавлен. При необходимости исправьте имя в карточке учащегося или дополните список.</p></div><div><h3>2. Заполняйте по парам или по дням</h3><p class="note">Во вкладке «День» нажмите отметку напротив человека. Пустая клетка означает присутствие; отдельно подтверждать его не нужно. В «Табеле» нажмите ячейку и вручную введите Б/8, ПН/2 или несколько причин: Б/4; ПН/2.</p></div><div><h3>3. Уточняйте причины без пересчёта</h3><p class="note">Нажмите фамилию, чтобы посмотреть историю и исправить записи. Суммы обновятся сразу. Последнее действие можно отменить кнопкой со стрелкой.</p></div><div><h3>4. Сверьте месяц и распечатайте</h3><p class="note">«Выгрузить» → «Печать / PDF». В диалоге печати выберите А4 и альбомную ориентацию, если браузер не применил их сам. Для переноса на другой телефон используйте резервную копию.</p></div></div><div class="note-box" style="margin-top:20px">Все семь обозначений, включая ПР, суммируются в «Всего». Каждый пропуск вы вносите вручную. Пустая клетка — присутствие.</div>`);}
function startDemo(){if(demo)return;realState=state;state=newState();demo=true;state.groups={'demo':makeGroup('4501 · пример','4501')};state.activeGroup='demo';state.theme=realState.theme;const g=group();g.students=['Андреев А. И.','Белов М. С.','Васильева Е. А.','Громов Д. В.','Данилова К. О.','Егоров Н. А.','Жукова А. Д.','Зайцев И. П.','Ильина М. А.','Козлов А. В.','Лебедева С. И.','Морозов П. Н.'].map((name,i)=>({id:`demo${i}`,name,rank:'',archived:false}));let available=monthDays(month).filter(d=>d<=selectedDate&&lessonsFor(schedule,g,d).some(l=>l.hours>0));for(const [j,d] of available.entries()){const ls=lessonsFor(schedule,g,d).filter(l=>l.hours>0);g.reviewed[d]=Object.fromEntries(ls.map(l=>[l.id,true]));g.marks[d]={};for(const [k,l] of ls.entries()){g.marks[d][l.id]={};for(let i=0;i<g.students.length;i++){if((i*7+j*3+k)%19===0||(i===1&&j>5&&j<10)){let code=i===1?'Б':['Б','ПН','УП','ОМ'][(i+j)%4];g.marks[d][l.id][g.students[i].id]={code,hours:l.hours,subject:l.subject,num:l.num,time:l.time,pe:l.pe};}}}}undoStack=[];query='';view='day';selectedLesson=null;render();toast('Открыт вымышленный пример. Ваш журнал не изменён.');}
function exitDemo(){state=realState;realState=null;demo=false;undoStack=[];query='';selectedLesson=null;render();}
async function refreshSchedule(){if(refreshing)return;refreshing=true;render();try{const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),20000);let r;try{r=await fetch(`https://qppaza.github.io/myschedule/index.html?refresh=${Date.now()}`,{cache:'no-store',signal:ctl.signal});}finally{clearTimeout(timer);}if(!r.ok)throw Error('network');const html=await r.text(),match=html.match(/\b(?:const|let)\s+SCHEDULE\s*=\s*(\{[^\n]*\});/);if(!match)throw Error('format');const data=JSON.parse(match[1]);if(!validSchedule(data)||!data.groups.includes('4502'))throw Error('format');schedule=data;scheduleUpdated=today();try{localStorage.setItem(SCHEDULE_KEY,JSON.stringify({data:schedule,updated:scheduleUpdated}));}catch{toast('Расписание обновлено, но его копия не сохранилась в браузере.');}toast('Расписание группы 4502 обновлено. Внесённые часы сохранены.');}catch{toast('Не удалось обновить с сайта. Загруженная копия сохранена; доступен импорт файла.');}finally{refreshing=false;render();}}
const actions={
 'close':closeModal,'go-day':()=>{view='day';render();},'nav':b=>{view=b.dataset.view;query='';render();},'today':()=>setDate(today()),'select-date':b=>setDate(b.dataset.date),'date-prev':()=>setDate(addDays(selectedDate,-7)),'date-next':()=>setDate(addDays(selectedDate,7)),
 'month-prev':()=>setMonth(addDays(month+'-01',-1).slice(0,7)),'month-next':()=>setMonth(addDays(monthDays(month).at(-1),1).slice(0,7)),
 'lesson':b=>{selectedLesson=b.dataset.id;render();},'lesson-new':()=>lessonDialog(),'lesson-edit':()=>lessonDialog(true),'roster':rosterDialog,'profile':b=>studentProfile(b.dataset.id),'edit-student':b=>editStudent(b.dataset.id),'status':b=>statusDialog(b.dataset.id),'daily':b=>dailyDialog(b.dataset.id,b.dataset.date||selectedDate),'bulk':bulkDialog,
 'review':()=>{const l=currentLesson();if(!l)return;change(()=>{group().reviewed[selectedDate]??={};group().reviewed[selectedDate][l.id]=true;},'Пара отмечена как сверенная');},
 'undo':()=>{if(!undoStack.length)return;state=JSON.parse(undoStack.pop());save();render();toast('Последнее действие отменено');},'theme':b=>openThemeMenu(b,state.theme,value=>{state.theme=value;save();render();}),'set-theme':b=>{state.theme=b.dataset.theme;save();render();},
 'save-group':()=>{const name=$('#groupName').value.trim(),source=$('#scheduleGroup').value;if(!name){toast('Введите название группы');return;}change(()=>{group().name=name;group().scheduleGroup=source;selectedLesson=null;},'Настройки группы сохранены');},
 'archive-student':b=>{const s=group().students.find(s=>s.id===b.dataset.id);if(!s||s.archived)return;confirmModal('Перенести учащегося в архив?',`${s.name} исчезнет из активного списка. История и месячные итоги сохранятся.`,()=>change(()=>s.archived=true,'Учащийся в архиве'),'В архив');},
 'restore-student':b=>change(()=>group().students.find(s=>s.id===b.dataset.id).archived=false,'Учащийся восстановлен'),
 'export':exportDialog,'backup':backup,'restore':()=>$('#fileInput').click(),'print':printTable,'html':()=>{download(printHTML(group(),month,state.includePR),`tabel-print-${month}.html`,'text/html;charset=utf-8');toast('Печатный табель скачан');},'csv':exportCsv,'help':help,'demo':startDemo,'exit-demo':exitDemo,
 'refresh-schedule':refreshSchedule,'import-schedule':()=>$('#scheduleInput').click(),'broken-download':()=>download(rawBroken||'',`tabel-recovery-${today()}.json`,'application/json'),
 'reset-broken':()=>confirmModal('Начать новый журнал?','Сначала скачайте исходные данные. Локальная нечитаемая копия будет заменена пустым журналом.',()=>{rawBroken=null;state=newState();undoStack=[];save();render();},'Начать заново')
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();actions[b.dataset.action]?.(b);});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='groupSelect'){if(t.value==='__new'){render();groupDialog();}else{state.activeGroup=t.value;selectedLesson=null;query='';save();render();}}if(t.id==='dateInput')setDate(t.value);if(t.id==='monthInput')setMonth(t.value);if(t.id==='includePR'){const value=t.checked;change(()=>state.includePR=value,'Правило подсчёта обновлено');}});
document.addEventListener('input',e=>{if(e.target.id==='studentSearch'){query=e.target.value;if(view==='day')$('#rosterContent').innerHTML=rosterHTML();else if(view==='students')$('#studentCards').innerHTML=studentCards(students().filter(s=>s.name.toLowerCase().includes(query.toLowerCase())));}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#fileInput').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>15e6)throw Error('Файл слишком большой');const parsed=JSON.parse(await f.text());if(parsed.kind!=='attendance-backup'||parsed.version!==1)throw Error('Выберите резервную копию табеля');const restored=validateState(parsed.state);if(restored.activeGroup!=='4502'||Object.keys(restored.groups).length!==1||!restored.groups['4502'])throw Error('Этот табель предназначен только для группы 4502');if(!validSchedule(parsed.schedule))throw Error('В резервной копии некорректное расписание');const count=Object.values(restored.groups).reduce((n,g)=>n+g.students.length,0);confirmModal('Восстановить журнал из копии?',`В копии: ${Object.keys(restored.groups).length} групп, ${count} учащихся. Текущий журнал группы 4502 в этом браузере будет заменён. Перед продолжением сохраните свою резервную копию, если она нужна.`,()=>{if(demo){demo=false;realState=null;}rawBroken=null;undoStack=[];state=restored;schedule=parsed.schedule;scheduleUpdated=parsed.scheduleUpdated||today();try{localStorage.setItem(SCHEDULE_KEY,JSON.stringify({data:schedule,updated:scheduleUpdated}));}catch{}selectedLesson=null;query='';save();render();toast('Журнал восстановлен');},'Восстановить');}catch(err){toast(err.message||'Не удалось прочитать файл');}};
$('#scheduleInput').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>10e6)throw Error('Файл слишком большой');const text=await f.text();let data;try{data=JSON.parse(text);}catch{const m=text.match(/\b(?:const|let)\s+SCHEDULE\s*=\s*(\{[^\n]*\});/);if(!m)throw Error('В файле не найдено расписание вашего сайта');data=JSON.parse(m[1]);}if(!validSchedule(data)||!data.groups.includes('4502'))throw Error('В расписании должна быть группа 4502');schedule=data;scheduleUpdated=today();try{localStorage.setItem(SCHEDULE_KEY,JSON.stringify({data:schedule,updated:scheduleUpdated}));}catch{toast('Копия расписания не сохранилась в браузере');}render();toast('Расписание импортировано');}catch(err){toast(err.message);}};
window.addEventListener('storage',e=>{if(demo)return;if(e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));undoStack=[];savedTime=state.updatedAt;closeModal();render();toast('Журнал обновлён в другой вкладке');}catch{}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!/INPUT|TEXTAREA/.test(e.target.tagName)&&!$('#modal').open){e.preventDefault();actions.undo();}});
document.body.classList.add('launch-motion');
render();
setTimeout(()=>document.body.classList.remove('launch-motion'),700);
